/* Cero Fugas - generador compartido de acuses PDF. Sin dependencias externas. */
(()=>{'use strict';
const LOGO='data:image/png;base64,', FONDO='data:image/jpeg;base64,';
const loadImage=src=>new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=reject;im.src=src});
const assets=()=>Promise.all([loadImage(LOGO),loadImage(FONDO)]);
const enc=new TextEncoder();
function pdf(jpeg,w,h){let parts=[],offset=0,xref=[0];const put=x=>{const a=typeof x==='string'?enc.encode(x):x;parts.push(a);offset+=a.length};const obj=(n,body)=>{xref[n]=offset;put(n+' 0 obj\n');put(body);put('\nendobj\n')};put('%PDF-1.4\n');obj(1,'<< /Type /Catalog /Pages 2 0 R >>');obj(2,'<< /Type /Pages /Kids [3 0 R] /Count 1 >>');obj(3,'<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << /XObject << /Im0 4 0 R >> >> /Contents 5 0 R >>');xref[4]=offset;put('4 0 obj\n<< /Type /XObject /Subtype /Image /Width '+w+' /Height '+h+' /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length '+jpeg.length+' >>\nstream\n');put(jpeg);put('\nendstream\nendobj\n');const content='q\n612 0 0 792 0 0 cm\n/Im0 Do\nQ\n';obj(5,'<< /Length '+enc.encode(content).length+' >>\nstream\n'+content+'endstream');let start=offset;put('xref\n0 6\n0000000000 65535 f \n'+xref.slice(1).map(x=>String(x).padStart(10,'0')+' 00000 n \n').join('')+'trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n'+start+'\n%%EOF\n');return new Blob(parts,{type:'application/pdf'})}
async function build(r){if(!/^[A-Z]{6}[0-9]{3,4}$/.test(r.apf)||!Number.isFinite(new Date(r.date).getTime())||typeof r.aa!=='boolean'||!Number.isSafeInteger(Number(r.count))||Number(r.count)<0||!Number.isFinite(Number(r.tr))||Number(r.tr)<0)throw Error('Datos del acuse no válidos');const [logo,bg]=await assets();const c=document.createElement('canvas');c.width=1530;c.height=1980;const x=c.getContext('2d');x.scale(2.5,2.5);const W=612,H=792;
function rect(a,b,w,h,color){x.fillStyle=color;x.fillRect(a,b,w,h)}function text(s,a,b,size,color='#252525',bold=false){x.font=(bold?'bold ':'')+size+'px Arial, sans-serif';x.fillStyle=color;x.fillText(s,a,b)}function line(a,b,d,e,color){x.strokeStyle=color;x.lineWidth=1;x.beginPath();x.moveTo(a,b);x.lineTo(d,e);x.stroke()}
rect(0,0,W,H,'#65132F');let scale=Math.max(W/bg.width,H/bg.height);x.drawImage(bg,(W-bg.width*scale)/2,(H-bg.height*scale)/2,bg.width*scale,bg.height*scale);rect(28,28,556,736,'#FFFFFF');rect(28,28,556,139,'#430F24');rect(28,165,556,4,'#A34D65');x.drawImage(logo,51,48,159,159*logo.height/logo.width);text('CERO FUGAS',51,128,25,'#FFFFFF',true);text('En la Administración Pública Federal',51,149,13,'#FFFFFF');
text('ACUSE DE RECEPCIÓN',52,207,24,'#430F24',true);text('Instrumento de recolección de información',52,230,12,'#545454');line(52,246,560,246,'#E3D5DA');
rect(52,266,508,72,'#F7F1F3');rect(52,266,4,72,'#24733E');x.strokeStyle='#24733E';x.lineWidth=2.5;x.beginPath();x.moveTo(69,293);x.lineTo(76,300);x.lineTo(89,285);x.stroke();text('Información recibida correctamente',100,290,16,'#24733E',true);text('Se confirma el registro de la información del inmueble',100,310,11);text('en la plataforma Cero Fugas.',100,325,11);
text('IDENTIFICACIÓN DEL REGISTRO',52,374,12,'#781D3F',true);text('Contraseña del inmueble en el sistema APF',52,398,11,'#555');text(r.apf,52,423,22,'#430F24',true);const dt=new Date(r.date);const date=new Intl.DateTimeFormat('es-MX',{timeZone:'America/Mexico_City',day:'2-digit',month:'long',year:'numeric'}).format(dt);const time=new Intl.DateTimeFormat('es-MX',{timeZone:'America/Mexico_City',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).format(dt);text('Fecha de registro',52,453,11,'#555');text('Hora de registro (CDMX)',316,453,11,'#555');text(date,52,473,14,'#252525',true);text(time,316,473,14,'#252525',true);
line(52,494,560,494,'#E3D5DA');text('RESUMEN DE INFORMACIÓN REPORTADA',52,520,12,'#781D3F',true);text('Utiliza equipos de aire acondicionado: '+(r.aa?'Sí':'No'),52,541,12);rect(52,556,246,76,'#F7F1F3');rect(314,556,246,76,'#F7F1F3');text('Número total de equipos',64,579,11,'#545454');text('Capacidad total instalada (TR)',326,579,11,'#545454');const num=new Intl.NumberFormat('en-US',{maximumFractionDigits:3});function fit(s,a,b,max){let z=25;while(z>11){x.font='bold '+z+'px Arial';if(x.measureText(s).width<=max)break;z--}text(s,a,b,z,'#430F24',true)}fit(num.format(Number(r.count)),64,612,222);fit(num.format(Number(r.tr)),326,612,222);
text('Este documento acredita la recepción de los datos declarados.',52,665,11,'#545454');text('No constituye una validación técnica de la información reportada.',52,681,11,'#545454');line(52,708,560,708,'#E3D5DA');text('Comisión Nacional para el Uso Eficiente de la Energía',52,732,11,'#430F24',true);text('Acuse generado electrónicamente',52,748,10,'#666');
const b64=c.toDataURL('image/jpeg',.94).split(',')[1];const jpg=Uint8Array.from(atob(b64),ch=>ch.charCodeAt(0));return pdf(jpg,c.width,c.height)}
window.CeroFugasAcuse={build,async download(r){const blob=await build(r);const u=URL.createObjectURL(blob);const a=document.createElement('a');a.href=u;a.download='Acuse_Cero_Fugas_'+r.apf+'.pdf';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),30000)}};
})();